INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (1, 1, 2, 'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ', 'Hamd, âlemlerin Rabbi olan Allah''a mahsustur.', 'Fâtiha Sûresi, 2', 'Hamd, âlemlerin Rabbi olan Allah''a mahsustur.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (2, 2, 152, 'فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ', 'Öyleyse yalnız beni anın ki ben de sizi anayım. Bana şükredin ve nankörlük etmeyin.', 'Bakara Sûresi, 152', 'Beni anın ki ben de sizi anayım; bana şükredin, nankörlük etmeyin.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (3, 2, 186, 'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ', 'Kullarım sana beni sorduklarında bilsinler ki şüphesiz ben yakınım. Bana dua edenin duasına icabet ederim.', 'Bakara Sûresi, 186', 'Şüphesiz ben yakınım; bana dua edenin duasına karşılık veririm.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (4, 2, 286, 'لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا', 'Allah hiçbir kimseye gücünün yettiğinden fazlasını yüklemez.', 'Bakara Sûresi, 286', 'Allah hiçbir kimseye gücünün yettiğinden fazlasını yüklemez.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (5, 3, 159, 'فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللَّهِ ۚ إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ', 'Karar verip azmettiğin zaman da artık Allah''a tevekkül et. Şüphesiz Allah, kendisine güvenenleri sever.', 'Âl-i İmrân Sûresi, 159', 'Karar verdiğin zaman Allah''a güven; Allah güvenenleri sever.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (6, 3, 173, 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', 'Allah bize yeter, O ne güzel vekildir!', 'Âl-i İmrân Sûresi, 173', 'Allah bize yeter, O ne güzel vekildir!') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (7, 7, 199, 'خُذِ الْعَفْوَ وَأْمُرْ بِالْعُرْفِ وَأَعْرِضْ عَنِ الْجَاهِلِينَ', 'Sen af yolunu tut, iyiliği emret ve cahillerden yüz çevir.', 'A''râf Sûresi, 199', 'Sen af yolunu tut, iyiliği emret ve cahillerden yüz çevir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (8, 9, 129, 'فَإِن تَوَلَّوْا فَقُلْ حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ', 'Yüz çevirirlerse de ki: Allah bana yeter. O''ndan başka ilah yoktur. Ben yalnızca O''na güvendim.', 'Tevbe Sûresi, 129', 'De ki: Allah bana yeter, O''ndan başka ilah yoktur; yalnız O''na dayandım.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (9, 13, 28, 'أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ', 'Bilesiniz ki kalpler ancak Allah''ı anmakla huzur bulur.', 'Ra''d Sûresi, 28', 'Bilesiniz ki kalpler ancak Allah''ı anmakla huzur bulur.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (10, 14, 7, 'لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ', 'Andolsun, eğer şükrederseniz elbette size olan nimetimi artırırım.', 'İbrâhîm Sûresi, 7', 'Andolsun, eğer şükrederseniz size olan nimetimi kesinlikle artırırım.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (11, 16, 128, 'إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَّالَّذِينَ هُم مُّحْسِنُونَ', 'Şüphesiz Allah, takva sahipleriyle ve iyilik yapanlarla beraberdir.', 'Nahl Sûresi, 128', 'Şüphesiz Allah, takva sahipleriyle ve iyilik yapanlarla beraberdir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (12, 17, 78, 'إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا', 'Çünkü sabah namazı şahitlidir (melekler ona tanıklık eder).', 'İsrâ Sûresi, 78', 'Çünkü sabah namazı meleklerin şahit olduğu bir vakittir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (13, 20, 114, 'وَقُل رَّبِّ زِدْنِي عِلْمًا', 'Ve de ki: Rabbim, ilmimi artır!', 'Tâhâ Sûresi, 114', 'Rabbim, benim ilmimi artır!') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (14, 21, 87, 'لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ', 'Senden başka hiçbir ilah yoktur. Seni tenzih ederim. Şüphesiz ben zalimlerden oldum.', 'Enbiyâ Sûresi, 87', 'Senden başka ilah yoktur. Seni tesbih ederim, ben haksızlık edenlerden oldum.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (15, 25, 63, 'وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا', 'Rahmân''ın kulları, yeryüzünde vakar ve tevazu ile yürüyen kimselerdir.', 'Furkân Sûresi, 63', 'Rahmân''ın kulları, yeryüzünde tevazu ile yürüyen kimselerdir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (16, 29, 45, 'إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ ۗ وَلَذِكْرُ اللَّهِ أَكْبَرُ', 'Şüphesiz namaz, insanı hayasızlıktan ve kötülükten alıkoyar. Allah''ı anmak ise en büyük ibadettir.', 'Ankebût Sûresi, 45', 'Şüphesiz namaz kötülükten alıkoyar. Allah''ı anmak en büyüktür.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (17, 33, 41, 'يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا', 'Ey iman edenler! Allah''ı çokça zikredin.', 'Ahzâb Sûresi, 41', 'Ey iman edenler! Allah''ı çokça zikredin.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (18, 39, 53, 'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ', 'De ki: Ey kendilerine kötülük edip aşırı giden kullarım! Allah''ın rahmetinden ümidinizi kesmeyin.', 'Zümer Sûresi, 53', 'Ey kullarım! Allah''ın rahmetinden ümit kesmeyin; Allah bütün günahları bağışlar.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (19, 40, 60, 'وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ', 'Rabbiniz buyurdu ki: Bana dua edin, size cevap vereyim.', 'Mü''min Sûresi, 60', 'Rabbiniz buyurdu: Bana dua edin, duanıza icabet edeyim.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (20, 49, 10, 'إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ', 'Müminler ancak kardeştirler. Öyleyse kardeşlerinizin arasını düzeltin.', 'Hucurât Sûresi, 10', 'Müminler ancak kardeştirler; kardeşlerinizin arasını düzeltin.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (21, 50, 16, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ', 'Biz insana şah damarından daha yakınız.', 'Kâf Sûresi, 16', 'Biz insana şah damarından daha yakınız.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (22, 55, 60, 'هَلْ جَزَاءُ الْإِحْسَانِ إِلَّا الْإِحْسَانُ', 'İyiliğin karşılığı, iyilikten başka bir şey midir?', 'Rahmân Sûresi, 60', 'İyiliğin mükâfatı ancak iyilik değil midir?') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (23, 57, 4, 'وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'Nerede olursanız olun O sizinle beraberdir. Allah yaptıklarınızı hakkıyla görendir.', 'Hadîd Sûresi, 4', 'Nerede olursanız olun O sizinle beraberdir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (24, 65, 3, 'وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ', 'Kim Allah''a tevekkül ederse, O kendisine yeter.', 'Talâk Sûresi, 3', 'Kim Allah''a güvenirse, Allah ona yeter.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (25, 93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 'Rabbin seni terk etmedi ve sana darılmadı.', 'Duhâ Sûresi, 3', 'Rabbin seni ne terk etti, ne de sana darıldı.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (26, 94, 5, 'فَإِنَّ مَعَ الْعُسْرِ يُسْرًا', 'Şüphesiz her zorlukla beraber bir kolaylık vardır.', 'İnşirâh Sûresi, 5', 'Kesinlikle her zorluğun yanında bir kolaylık vardır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (27, 94, 6, 'إِنَّ مَعَ الْعُسْرِ يُسْرًا', 'Evet, her zorlukla beraber muhakkak bir kolaylık vardır.', 'İnşirâh Sûresi, 6', 'Gerçekten de her zorlukla beraber bir kolaylık vardır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (28, 103, 1, 'وَالْعَصْرِ ۝ إِنَّ الْإِنسَانَ لَفِي خُسْرٍ', 'Asra yemin olsun ki, insan gerçekten ziyan içindedir.', 'Asr Sûresi, 1-2', 'Zamana yemin olsun ki, insan gerçekten hüsrandadır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (29, 112, 1, 'قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ', 'De ki: O Allah tektir. Allah Samed''dir (her şey O''na muhtaçtır, O hiçbir şeye muhtaç değildir).', 'İhlâs Sûresi, 1-2', 'De ki: O Allah tektir; Allah Samed''dir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_verses (day_of_year, surah_no, ayah_no, arabic, meal_tr, source_name, short_text) VALUES (30, 114, 1, 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ', 'De ki: İnsanların Rabbine, insanların yegâne hükümdarına sığınırım.', 'Nâs Sûresi, 1-2', 'De ki: İnsanların Rabbine ve hükümdarına sığınırım.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, meal_tr = EXCLUDED.meal_tr, source_name = EXCLUDED.source_name, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (1, 'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ', 'Ameller niyetlere göredir; herkesin niyeti ne ise eline geçecek olan odur.', 'Hz. Ömer (r.a.)', 'Buhârî', 'Bed''ü''l-Vahy 1', 'Ameller niyetlere göredir; herkes için ancak niyet ettiği şey vardır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (2, 'المُسْلِمُ مَنْ سَلِمَ المُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ', 'Müslüman, dilinden ve elinden diğer Müslümanların güvende olduğu kimsedir.', 'Abdullah b. Amr (r.a.)', 'Buhârî', 'Îmân 4', 'Müslüman, diğer Müslümanların elinden ve dilinden selamette olduğu kimsedir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (3, 'لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ', 'Sizden biriniz, kendisi için istediğini din kardeşi için de istemedikçe gerçek manada iman etmiş olamaz.', 'Enes b. Mâlik (r.a.)', 'Buhârî', 'Îmân 7', 'Kendisi için istediğini kardeşi için de istemedikçe kamil mümin olamaz.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (4, 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ', 'Allah''a ve ahiret gününe inanan kimse ya hayır söylesin yahut sussun.', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Edeb 31', 'Allah''a ve ahirete inanan ya hayır söylesin yahut sussun.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (5, 'الطَّهُورُ شَطْرُ الإِيمَانِ', 'Temizlik imanın yarısıdır.', 'Ebû Mâlik el-Eş''arî (r.a.)', 'Müslim', 'Tahâret 1', 'Temizlik imanın yarısıdır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (6, 'الصَّلاةُ نُورٌ', 'Namaz bir nurdur; sadaka delildir; sabır ise aydınlıktır.', 'Ebû Mâlik el-Eş''arî (r.a.)', 'Müslim', 'Tahâret 1', 'Namaz nurdur, sabır ise ışıktır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (7, 'لا تَحَاسَدُوا، وَلا تَبَاغَضُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا', 'Birbirinize haset etmeyiniz, birbirinize buğzetmeyiniz; ey Allah''ın kulları, kardeş olunuz!', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Edeb 57', 'Birbirinize haset etmeyin, kin beslemeyin; kardeş olun!') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (8, 'اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الحَسَنَةَ تَمْحُهَا', 'Nerede olursan ol Allah''tan kork; kötülüğün peşinden hemen bir iyilik yap ki onu silsin.', 'Ebû Zer (r.a.)', 'Tirmizî', 'Birr 55', 'Nerede olursan ol Allah''tan sakın; kötülüğün ardına iyilik ekle.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (9, 'خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ', 'Sizin en hayırlınız Kur''an''ı öğrenen ve öğreteninizdir.', 'Hz. Osman (r.a.)', 'Buhârî', 'Fedâilü''l-Kur''ân 21', 'En hayırlınız, Kur''an''ı öğrenen ve başkalarına öğreteninizdir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (10, 'كَلِمَتَانِ حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', 'Dile hafif, mizanda ağır, Rahmân''a sevgili iki kelime: Sübhânallâhi ve bi-hamdihî, Sübhânallâhi''l-azîm.', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Daavât 65', 'Dile hafif, mizanda ağır iki zikir: Sübhanallahi ve bihamdihi, Sübhanallahil-azim.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (11, 'الدِّينُ النَّصِيحَةُ', 'Din, samimiyettir (Allah''a, kitabına, peygamberine ve bütün müminlere karşı samimi ve dürüst olmaktır).', 'Temîm ed-Dârî (r.a.)', 'Müslim', 'Îmân 95', 'Din, samimiyettir ve içtenliktir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (12, 'اليَدُ العُلْيَا خَيْرٌ مِنَ اليَدِ السُّفْلَى', 'Veren el, alan elden daha hayırlıdır.', 'Abdullah b. Ömer (r.a.)', 'Buhârî', 'Zekât 18', 'Veren el, alan elden hayırlıdır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (13, 'تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ', 'Kardeşinin yüzüne tebessüm etmen senin için bir sadakadır.', 'Ebû Zer (r.a.)', 'Tirmizî', 'Birr 36', 'Kardeşinin yüzüne tebessüm etmen bir sadakadır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (14, 'يَسِّرُوا وَلا تُعَسِّرُوا، وَبَشِّرُوا وَلا تُنَفِّرُوا', 'Kolaylaştırınız, zorlaştırmayınız; müjdeleyiniz, nefret ettirmeyiniz.', 'Enes b. Mâlik (r.a.)', 'Buhârî', 'İlim 11', 'Kolaylaştırın, zorlaştırmayın; müjdeleyin, nefret ettirmeyin.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (15, 'مَنْ صَلَّى عَلَيَّ صَلاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا', 'Kim bana bir salavat getirirse, Allah Teâlâ buna karşılık ona on rahmet bahşeder.', 'Ebû Hüreyre (r.a.)', 'Müslim', 'Salât 70', 'Kim bana bir salavat getirirse, Allah ona on kat rahmet eder.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (16, 'أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ', 'Allah katında amellerin en sevimlisi, az da olsa devamlı olanıdır.', 'Hz. Âişe (r.a.)', 'Buhârî', 'Rikâk 18', 'Allah katında amellerin en sevimlisi, az da olsa sürekliliktir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (17, 'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الجَنَّةِ', 'Kim ilim öğrenmek için bir yola çıkarsa, Allah ona cennet yolunu kolaylaştırır.', 'Ebû Hüreyre (r.a.)', 'Müslim', 'Zikir 38', 'İlim peşinde koşan kimseye Allah cennet yolunu kolaylaştırır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (18, 'إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ', 'Şüphesiz Allah yumuşak huyludur (Rıfk sahibidir) ve her işte nezaket ve zarafeti sever.', 'Hz. Âişe (r.a.)', 'Buhârî', 'Edeb 35', 'Şüphesiz Allah her işte nezaket ve yumuşaklığı sever.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (19, 'لا يُلْدَغُ المُؤْمِنُ مِنْ جُحْرٍ وَاحِدٍ مَرَّتَيْنِ', 'Mümin, bir delikten iki defa ısırılmaz (aynı hataya iki kez düşmez).', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Edeb 83', 'Mümin, bir delikten iki defa ısırılmaz; feraset sahibidir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (20, 'مَنْ لا يَرْحَمُ النَّاسَ لا يَرْحَمُهُ اللَّهُ', 'İnsanlara merhamet etmeyene Allah da merhamet etmez.', 'Cerîr b. Abdullah (r.a.)', 'Buhârî', 'Edeb 18', 'İnsanlara merhamet göstermeyene Allah merhamet etmez.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (21, 'عَجَبًا لأَمْرِ المُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ', 'Müminin durumuna hayret edilir! Her işi hayırdır; nimete şükreder hayır olur, sıkıntıya sabreder hayır olur.', 'Süheyb (r.a.)', 'Müslim', 'Zühd 64', 'Müminin her hali hayırdır: Sevinir şükreder, üzülür sabreder.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (22, 'الصِّدْقُ يَهْدِي إِلَى البِرِّ وَإِنَّ البِرَّ يَهْدِي إِلَى الجَنَّةِ', 'Doğruluk iyiliğe, iyilik ise cennete götürür.', 'Abdullah b. Mes''ûd (r.a.)', 'Buhârî', 'Edeb 69', 'Doğruluk insanı iyiliğe, iyilik ise cennete ulaştırır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (23, 'مَنْ حَسُنَ إِسْلامُ المَرْءِ تَرْكُهُ مَا لا يَعْنِيهِ', 'Kendisini ilgilendirmeyen mâlâyâni şeyleri terk etmesi, kişinin iyi bir Müslüman oluşundandır.', 'Ali b. Hüseyin (r.a.)', 'Tirmizî', 'Zühd 11', 'Kendisini ilgilendirmeyen boş şeyleri terk etmek, kişinin olgunluğundandır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (24, 'لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الغَضَبِ', 'Gerçek pehlivan güreşte rakibini yenen değil, öfkelendiği an nefsine hakim olan kimsedir.', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Edeb 76', 'Gerçek güçlü, öfkelendiği anda iradesine ve nefsine hâkim olandır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (25, 'أَفْشُوا السَّلامَ بَيْنَكُمْ', 'İman etmedikçe cennete giremezsiniz; birbirinizi sevmedikçe de kamil iman etmiş olamazsınız. Aranızda selamı yayınız!', 'Ebû Hüreyre (r.a.)', 'Müslim', 'Îmân 93', 'Birbirinizi sevmedikçe iman etmiş olmazsınız. Aranızda selâmı yayınız.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (26, 'حَقُّ المُسْلِمِ عَلَى المُسْلِمِ خَمْسٌ: رَدُّ السَّلامِ، وَعِيَادَةُ المَرِيضِ', 'Müslümanın Müslüman üzerindeki hakkı beştir: Selama karşılık vermek, hastayı ziyaret etmek, cenazeye katılmak, davete icabet etmek ve aksırana ''yerhamükellah'' demek.', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Cenâiz 2', 'Müslümanın kardeşi üzerinde beş hakkı vardır: Selam, ziyaret, cenaze, davet, dua.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (27, 'مَنْ كَانَتْ لَهُ مَظْلَمَةٌ لأَخِيهِ فَلْيَتَحَلَّلْهُ مِنْهُ اليَوْمَ', 'Kimin üzerinde kardeşine ait bir hak varsa, altın ve gümüşün bulunmayacağı hesap günü gelmeden önce helalleşsin.', 'Ebû Hüreyre (r.a.)', 'Buhârî', 'Mezâlim 10', 'Üzerinde kul hakkı bulunan kimse, hesap günü gelmeden önce dünyada helalleşsin.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (28, 'إِنَّ الصَّدَقَةَ لَتُطْفِئُ غَضَبَ الرَّبِّ', 'Gizlice verilen sadaka, Rabb''in gazabını dindirir ve kötü bir ölüme engel olur.', 'Muâz b. Cebel (r.a.)', 'Tirmizî', 'Zekât 28', 'Gizli sadaka Rabb''in gazabını dindirir ve kötülüklere kalkan olur.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (29, 'الدُّعَاءُ هُوَ العِبَادَةُ', 'Dua, ibadetin ta kendisidir.', 'Nu''mân b. Beşîr (r.a.)', 'Ebû Dâvûd', 'Vitr 23', 'Dua ibadetin özü ve ta kendisidir.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;
INSERT INTO public.daily_hadiths (day_of_year, arabic, text_tr, narrator, source_book, source_no, short_text) VALUES (30, 'كُلُّ مَعْرُوفٍ صَدَقَةٌ', 'Yapılan her meşru iyilik bir sadakadır.', 'Câbir b. Abdullah (r.a.)', 'Buhârî', 'Edeb 33', 'Her güzel ve meşru iyilik bir sadakadır.') ON CONFLICT (day_of_year) DO UPDATE SET arabic = EXCLUDED.arabic, text_tr = EXCLUDED.text_tr, narrator = EXCLUDED.narrator, source_book = EXCLUDED.source_book, source_no = EXCLUDED.source_no, short_text = EXCLUDED.short_text;